"Raider: LMB — 4-rocket salvo, RMB — MG, {0} — nitro. Fast and fragile: hit builders and flanks.":"Ρέιντερ: LMB — ομοβροντία 4 ρουκετών, RMB — πολυβόλο, {0} — νίτρο. Γρήγορο και εύθραυστο: χτύπα μηχανικούς και τα πλευρά.",
"MLRS: LMB — salvo at the aim point (35–160 m), RMB — high view for far targets, {0} — smoke salvo.":"MLRS: LMB — ομοβροντία στο σημείο στόχευσης (35–160 m), RMB — άποψη από ψηλά για μακρινούς στόχους, {0} — καπνογόνα ομοβροντία.",
"{0}: LMB — lob at the aim point, RMB — high view, {1} — flare bomb (spotting).":"{0}: LMB — βολή με καμπύλη τροχιά στο σημείο στόχευσης, RMB — άποψη από ψηλά, {1} — φωτιστική βόμβα (ανίχνευση).",
