"New in v6.3":"Νέα στην v6.3",
"New in v6.2":"Νέα στην v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Νέα όψη μεταλλεύματος: οι φλέβες είναι λαμπερά πολύπλευρα σμαραγδένια κρύσταλλα σε μαύρο βασάλτη με σπίθες και πράσινη ομίχλη· ο εξορύκτης είναι εξαγωνική βάση με κηρήθρα-θόλο και πυργίσκο-πλέγμα με πράσινο φανάρι (λωρίδα και σημαιάκι στο χρώμα της ομάδας)",
"New in v6.1":"Νέα στην v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Προτιμώμενη κλάση όπως στο Battlefield (U, αριθμοί μετά τον θάνατο): κάνεις respawn σε αυτήν όταν είναι διαθέσιμη",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Οχήματα σε πρώτο πρόσωπο (V — έξω/καμπίνα)· ήπια υποβοήθηση στόχευσης — στις Ρυθμίσεις",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Εύκολη έξοδος από τον πυρήνα: Space — στο φρέαρ, B — κάψουλα στην επιφάνεια· τα εφέ ικανοτήτων μηδενίζονται με τον θάνατο",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Ατελείωτη πρόοδος: στρατηγοί και Στρατάρχης ★, επίπεδα καριέρας, μαεστρία όπλων και αξεσουάρ, μετάλλια, καθημερινά συμβόλαια — οθόνη «Καριέρα»",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Στρατηγική: ομαλό ζουμ με τον τροχό, εικονίδια και ετικέτες πάνω από τις μονάδες (Alt — όλες), πάνελ «Στρατεύματα / Κτίρια» αριστερά",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"Δεξί κλικ — κίνηση με μάχη στη διαδρομή, διπλό δεξί κλικ — πορεία με πυρά εν κινήσει· σπάνιες εντολές στο «Περισσότερες εντολές ▾»· χωρίς διπλά κουμπιά",
"New in v6":"Νέα στο v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Όπλα σαν σε σκοπευτικό: στιγμιαίες σφαίρες, τυφέκιο 720 βολές/λεπτό, πολυβόλο, ανάκρουση, σκόπευση με δεξί κλικ, γεμιστήρες και ανανέωση με R, δείκτες χτυπημάτων",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Βαρύτερη βαρύτητα, ευαίσθητο τζετπάκ, ώθηση με Z ή διπλό τζετπάκ στον αέρα· το όπλο δεν πετάει πια μαζί σου όταν αλλάζεις μονάδα",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Μηχανικοί: επίλεξε μηχανικό, διάλεξε κτίριο, τοποθέτησε σχέδιο· Εξορύκτες σε φλέβες μεταλλεύματος· κλικ στο «ΜΕΤΑΛΛ.» για να δεις έσοδα και πώς να τα αυξήσεις",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Τα γκρίζα κουμπιά εξηγούν τον λόγο και προτείνουν λύση· μεγαλύτερα κουμπιά, λωρίδα «Σε εξέλιξη», «▶ Έλεγχος», το Tab είναι το ενιαίο πλήκτρο λειτουργίας",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Κάμερα στρατηγικής χωρίς αναπηδήσεις και αναστροφές, ζουμ προς τον κέρσορα, ο χάρτης μπορεί να σύρεται",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Νέα οχήματα: ληστής \"Jackal\", πολλαπλός εκτοξευτής \"Grad\" (ρουκέτες με αυτοκαθοδήγηση), όλμος \"Hammer\"· το Σμήνος παίρνει \"Wasp\", \"Hive\", \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Ο AI στρατηγός κρατά τις εντολές και δεν γεμίζει το ραδιόφωνο φωνές· οι μάχες έρχονται σε σένα· B — μεταφορά, Shift+B — στη μάχη· πυξίδα, H — ποιος στόχος",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Ελεύθερη δράση (K) και μόνος μου (J), F2 — προρρυθμίσεις· Esc — παύση και επιστροφή· αποθηκεύσεις: θέσεις, εξαγωγή και εισαγωγή αρχείου",
"New in v5.3":"Νέα στο v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Πτήση: ισχυρότερη βαρύτητα μακριά από τον μετεωρίτη, C στον αέρα — φρένο, η ώθηση στρίβει πιο απότομα· δεν «κολλάς» πια στην πύλη",
"New in v5":"Νέα στο v5",
"Endless war by default and battle scale: normal, large, epic":"Ατελείωτος πόλεμος από προεπιλογή και κλίμακα μαχών: κανονική, μεγάλη, επική",
"Save and load the battle (autosave every 3 minutes)":"Αποθήκευση και φόρτωση μάχης (και αυτόματη αποθήκευση κάθε 3 λεπτά)",
"Squadmates with callsigns: portraits, health and live chatter":"Ομάδα με ονόματα κλήσης: πορτρέτα, υγεία και ζωντανή επικοινωνία",
"Fog of war in strategy, friends and foes outlined differently":"Ομίχλη πολέμου στη στρατηγική, φίλοι και εχθροί με διαφορετικό περίγραμμα",
"Camera fly-over when switching, portal aurora instead of rings":"Πτήση κάμερας κατά την εναλλαγή, σέλας της πύλης αντί για δακτυλίους",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Δευτερεύουσες αποστολές, συντόμευση μέσω ουρανού, οικισμοί της πρώτης αποστολής με προμήθειες, κρύσταλλοι, πάγος στους κρατήρες, θύελλες σκόνης",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Εκπαίδευση, κινηματογραφική λειτουργία με εγγραφή βίντεο, οχήματα συνοδείας από τον στρατηγό",
