"Redeploy: pod to objective / into the fight":"Μεταφορά: κάψουλα σε στόχο / στο κέντρο της μάχης",
"The objective is far. {0} — drop pod straight to it (with your squad). Shift+{1} — possess a trooper in the thick of the fight.":"Ο στόχος είναι μακριά. {0} — κάψουλα κατευθείαν σε αυτόν (με την ομάδα σου). Shift+{1} — Έλεγχος ενός λόχου στο κέντρο της μάχης.",
"Intel: a Swarm squad is heading your way — {0}, about {1} meters.":"Πληροφορίες: ομάδα του Σμήνους κατευθύνεται προς εσάς — {0}, περίπου {1} μέτρα.",
"Contact from above! A Swarm pod is coming down {0}, {1} meters!":"Επαφή από ψηλά! Κάψουλα του Σμήνους πέφτει {0}, {1} μέτρα!",
"Swarm signaller {0}! It will call a drop in 12 seconds — kill it first!":"Σηματοδότης του Σμήνους {0}! Σε 12 δευτερόλεπτα θα καλέσει επιδρομή — σκότωσέ τον πρώτα!",
"Signaller down — no drop.":"Ο σηματοδότης έπεσε — δεν θα υπάρξει επιδρομή.",
"The signaller got it off! Swarm pod inbound.":"Ο σηματοδότης πρόλαβε! Κάψουλα του Σμήνους καταφθάνει.",
"The Swarm is counter-attacking {0}! Get ready to defend.":"Το Σμήνος αντεπιτίθεται {0}! Ετοιμαστείτε για άμυνα.",
"You're going solo. {0} returns to the strategist. {1} — call them back.":"Δρας μόνος σου. Ο/Η {0} περνά υπό τις διαταγές του στρατηγού. {1} — κάλεσέ τον πίσω.",
"No free squads nearby — you stay solo for now.":"Δεν υπάρχουν ελεύθερες ομάδες κοντά — προς το παρόν μένεις μόνος.",
"{0}: on our way to you, commander!":"{0}: κατευθυνόμαστε προς εσένα, διοικητά!",
"{0} is with you again.":"Η {0} είναι ξανά μαζί σου.",
"Mode: going solo":"Λειτουργία: μόνος μου",
"Mode: squad with me":"Λειτουργία: ομάδα μαζί μου",
