"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"Χειροβομβίδα: κράτα G — θα δεις την τροχιά και τον κύκλο έκρηξης· σύρε το δάχτυλο στο κουμπί — γωνία· άφησε — ρίψη.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"Χειροβομβίδα: κράτα {0} για την τροχιά και τον κύκλο έκρηξης, άφησε για ρίψη. Βεληνεκές — με τη γωνία βλέμματος, τροχός — δύναμη, δεξί κλικ — κάτω.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"Χειροβομβίδες: κράτα G — τροχιά πτήσης, σημείο και κύκλος έκρηξης, απόσταση· άφησε — ρίψη. Βεληνεκές με τη γωνία βλέμματος, τροχός — δύναμη, δεξί κλικ — κάτω",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"Οι χειροβομβίδες αναπηδούν και κυλούν στις πλαγιές, έκρηξη σε 2,5 δ.· 2 χειροβομβίδες, ανανέωση 9 δ.· εικονίδιο προειδοποίησης για εχθρική χειροβομβίδα κοντά",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"Χειροβομβίδα: κράτημα — τροχιά και σημείο έκρηξης, άφημα — ρίψη · υπερφόρτιση άρματος",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — κράτα: φαίνεται η τροχιά και ο κύκλος έκρηξης, άφησε για ρίψη. Έκρηξη σε 2,5 δ., 2 χειροβομβίδες.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Χειροβομβίδα ({0}): κράτα — τροχιά πτήσης, σημείο και κύκλος έκρηξης, απόσταση· άφησε — ρίψη· σύντομο πάτημα — άμεση ρίψη. Βεληνεκές με τη γωνία βλέμματος, τροχός — δύναμη, δεξί κλικ — κάτω. Κινητό: κράτα G και σύρε το δάχτυλο.",
