"🛠 Developer mode: everything unlocked, endless ore. Arsenal — F8 or the \"🛠 Arsenal\" button.":"🛠 Λειτουργία προγραμματιστή: όλα ξεκλείδωτα, ατέλειωτο μετάλλευμα. Οπλοστάσιο — F8 ή κουμπί «🛠 Οπλοστάσιο».",
"Developer mode off (the match stays flagged — career is not saved)":"Η λειτουργία προγραμματιστή απενεργοποιήθηκε (ο αγώνας παραμένει σημαδεμένος — η καριέρα δεν αποθηκεύεται)",
"Battle saves are disabled in developer mode":"Οι αποθηκεύσεις μάχης είναι απενεργοποιημένες στη λειτουργία προγραμματιστή",
