"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Πάτα «Σκόπευση» για ζουμ. Ξανά πάτημα για έξοδο.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Η ομάδα σε ακολουθεί. Άνοιξε ☰ → «Παύση» → το πλακίδιο «Ομάδα μαζί μου» — γίνεται «Δράση μόνος».",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Ο μηχανικός επιλέχθηκε — πάτα «◆ Εξόρυξη κρυστάλλων» στην κάρτα του κάτω (ή πάτα τους πράσινους κρυστάλλους).",
