"Strategy: simple (engineer & buildings)":"Στρατηγική: απλή (μηχανικός και κτίρια)",
"Possession: ":"Έλεγχος: ",
"squads":"ομάδες",
"vehicles":"οχήματα",
" · AI drives vehicles, E next to one — man its gun":" · το όχημα οδηγεί το AI, E δίπλα σε όχημα — πάρε το πυροβόλο",
"Possess squads (infantry)":"Έλεγχος ομάδων (πεζικό)",
"Possess vehicles and drones":"Έλεγχος οχημάτων και drone",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"Στο πυροβόλο: {0}. Οδηγεί το AI, εσύ πυροβολείς. {1} — κατέβα",
"The vehicle is destroyed — you jumped off":"Το όχημα καταστράφηκε — πήδηξες έξω",
"{0} — get off the gun":"{0} — κατέβα από το πυροβόλο",
"{0} — man the gun: {1}":"{0} — πάρε το πυροβόλο: {1}",
"Combo ×{0} · reflex +{1}%":"Κόμπο ×{0} · αντανακλαστικό +{1}%",
"Strategist: troopers dropping to you — +{0} (−{1} ore)":"Στρατηγός: στρατιώτες προς εσένα με κάψουλα — +{0} (−{1} μετάλλευμα)",
"Hold on, sending troopers your way":"Κράτα, σου στέλνω ενίσχυση",
"· basic{0}":"· βασικές{0}",
"· advanced":"· προχωρημένες",
"· rare":"· σπάνιες",
"Advanced: class order":"Για προχωρημένους: σειρά κλάσεων",
"Voice of hints and curator":"Φωνή συμβουλών και Οδηγού",
"Advanced: custom class order":"Για προχωρημένους: δική σου σειρά κλάσεων",
"Voice of hints & curator":"Φωνή συμβουλών και Οδηγού",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Κινητό: τρεις τρόποι μοχλών. Μόνο αριστερός — «αυτόματο» (δυνατός μαγνήτης, πιο αδύναμες σφαίρες). Μόνο δεξιός — ενεργοποιείται μόνος του ο σκοπευτής, δυνατότερος μαγνήτης, καλύτερη ακρίβεια. Και οι δύο — χωρίς σκόπευση, πιο αδύναμος μαγνήτης και ακρίβεια. Το κουμπί 👁 δεξιά κρύβει/επαναφέρει το περιβάλλον.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Κινητό: απλοποιημένη στρατηγική — μόνο μηχανικός και κτίρια. Κάρτες αριστερά (μηχανικός, Στρατηγείο, Στρατώνας…): πάτημα — η κάμερα πηγαίνει εκεί, η κάτω μπάρα δείχνει τι να χτίσεις/παράγεις. «Στη μάχη» — πάνω αριστερά. Ο στρατός πολεμά μόνος του. Πλήρης στρατηγική — Ρυθμίσεις → Κινητό.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Έλεγχος — δύο διακόπτες: «Ομάδες» και «Οχήματα» (στο κινητό τα οχήματα είναι απενεργοποιημένα από προεπιλογή — τα οδηγεί το AI). Με απενεργοποιημένα τα οχήματα, το E (κινητό: το κουμπί δεξιά) δίπλα σε φιλικό όχημα — πάρε το πυροβόλο του: το όχημα κινείται μόνο του, εσύ πυροβολείς. Η παλιά «δική σου σειρά κλάσεων» είναι στα «Για προχωρημένους». Όταν αναλαμβάνεις μια μονάδα, απαντά στον ασύρματο.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Έξυπνες συμβουλές: οι βασικές σβήνουν μόνες μετά την 2η εκκίνηση, αλλά το παιχνίδι θα υποδείξει μια λειτουργία που δεν χρησιμοποιείς ποτέ. Διακόπτες: βασικές / προχωρημένες / σπάνιες, και ξεχωριστά για τη φωνή συμβουλών και Οδηγού.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Το αντανακλαστικό φορτίζει από σκοτωμούς (οι σειρές φορτίζουν περισσότερο). Οι συμπαίκτες έμειναν πίσω ή πέθαναν — ο στρατηγός ρίχνει νέους κοντά σου (ακριβότερα από την κανονική ενίσχυση). Τα γραφικά και ο ήχος v7.2gfx ενσωματώθηκαν: εκρήξεις σε σύννεφα, καπνός, συντρίμμια, ακουστική φρεατίων και κρατήρων. Η ημερομηνία έκδοσης είναι πλέον αληθινή.",
