"Follow the strategist's orders — XP for them is doubled and tripled.":"Εκτέλεσε τις εντολές του στρατηγού — η εμπειρία γι' αυτές διπλασιάζεται και τριπλασιάζεται.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — άμεση εναλλαγή στην ομάδα ή το όχημα που είναι πιο κοντά στη μάχη.",
"Bullets hit hardest at medium range, 20–50 meters.":"Οι σφαίρες χτυπούν πιο δυνατά σε μέση απόσταση, 20–50 μέτρα.",
"To win, destroy the Swarm HQ and all its key buildings.":"Για να νικήσεις, γκρέμισε το Στρατηγείο του Σμήνους και όλα τα βασικά του κτίρια.",
