"◎ right only (aim) — strength & radius":"◎ μόνο δεξί (σκόπευση) — ισχύς και ακτίνα",
"○ both fingers (free)":"○ και τα δύο δάχτυλα (ελεύθερο)",
"Reset: 1 · 1.8 · 0.5":"Επαναφορά: 1 · 1.8 · 0.5",
"developer mode: all 4 trainings":"λειτουργία προγραμματιστή: και οι 4 εκπαιδεύσεις",
"ON: endless ore, all unlocked":"ΕΝΕΡΓΟ: ατέλειωτο μετάλλευμα, όλα ξεκλείδωτα",
"OFF (turn on)":"ΑΝΕΝΕΡΓΟ (ενεργοποίηση)",
"Trainings (all 4)":"Εκπαιδεύσεις (και οι 4)",
"DEVELOPER":"ΠΡΟΓΡΑΜΜΑΤΙΣΤΗΣ",
"Developer: mode, arsenal, range":"Προγραμματιστής: λειτουργία, οπλοστάσιο, πεδίο δοκιμών",
"sandbox · all trainings · cinema":"πεδίο δοκιμών · όλες οι εκπαιδεύσεις · σινεμά",
"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Η Καριέρα και οι αποθηκεύσεις δεν αλλάζουν. Στη μάχη το ίδιο μενού είναι το κουμπί «🛠 Μενού» πάνω δεξιά{0}.",
"New developer match":"Νέος αγώνας προγραμματιστή",
"all unlocked, endless ore, instant build, arsenal":"όλα ξεκλείδωτα, ατέλειωτο μετάλλευμα, άμεσο χτίσιμο, οπλοστάσιο",
"Trainings — all 4":"Εκπαιδεύσεις — και οι 4",
"PC and phone (strategy and shooter)":"PC και κινητό (στρατηγική και σκοπευτής)",
"Cinema: split screen":"Σινεμά: διαχωρισμένη οθόνη",
"strategist bot left, shooter bot right":"bot-στρατηγός αριστερά, bot-σκοπευτής δεξιά",
"Cinema: everything built":"Σινεμά: όλα χτισμένα",
"both bases built and upgraded — for footage":"και οι δύο βάσεις χτισμένες και αναβαθμισμένες — για λήψη υλικού",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Λειτουργία σινεμά — διαχωρισμένη οθόνη: αριστερά το bot-στρατηγός (κάτοψη της βάσης και του στρατού), δεξιά το bot-σκοπευτής σε πρώτο πρόσωπο. Κουμπιά κάτω (και πλήκτρα S, P): «Διαχωρισμένη οθόνη» και «★ Όλα χτισμένα» — και οι δύο βάσεις χτισμένες και αναβαθμισμένες για λήψη υλικού.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Ο Πυρήνας και οι σήραγγες μέσα στον μετεωρίτη δεν υπάρχουν πια — ο μετεωρίτης είναι συμπαγής, η μάχη γίνεται μόνο στην επιφάνεια.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Κινητό: το 👁 κρύβει το HUD αλλά κρατά το jetpack, το ⇆, τα stick και τον δείκτη στόχου. «◎ Σκόπευση» (μόνο με το δεξί δάχτυλο) — αισθητά πιο δυνατός και πιο πλατύς μαγνήτης· ο μαγνήτης για τους τρεις τρόπους — Ρυθμίσεις → Χειρισμός → «Για προχωρημένους». Στο πολυβόλο οχήματος το κουμπί γράφει «Κατέβα».",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Εκπαίδευση: στο κινητό μόνο οι εκπαιδεύσεις για κινητό, στο PC μόνο για PC. Και οι 4 βρίσκονται στο μενού «🛠 Προγραμματιστής». Ο τρόπος προγραμματιστή και το Οπλοστάσιο είναι πλέον ένα μενού (στη μάχη — «🛠 Μενού» πάνω δεξιά, στο PC και F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Στυλ γραφικών «Dendy (8-bit)» και «16-bit»: Ρυθμίσεις → Γραφικά → «Στυλ γραφικών» (λεπτομέρειες — κουμπί ⚙). Αν τα FPS είναι κάτω από 24 στα πρώτα ~10 s του αγώνα, το Dendy ενεργοποιείται μόνο του (κάτω από 20 — μεγαλύτερα pixel, 120 γραμμές)· η ειδοποίηση «επιστροφή στα κανονικά» επαναφέρει μόνιμα τα κανονικά γραφικά. Η δική σου επιλογή στο μενού υπερισχύει πάντα.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D μοντέλα περιβάλλοντος (ερείπια, συντρίμμια, οχυρώσεις) — μόνο όσα έχουν καλές βαθμολογίες, φορτώνονται κατά απαίτηση. Απενεργοποίηση: Ρυθμίσεις → Γραφικά → «Νέα 3D μοντέλα περιβάλλοντος».",
"New in v7.5":"Τι νέο στο v7.5",
"NEW IN v7.5":"ΤΙ ΝΕΟ ΣΤΟ v7.5",
"Built by the squad: {0}":"Χτίστηκαν από την ομάδα: {0}",
"Trooper, the engineers are busy — help finish the {0}, {1} m. {2} at the site.":"Στρατιώτη, οι μηχανικοί είναι απασχολημένοι — βοήθησε να ολοκληρωθεί: {0}, {1} m. {2} στο εργοτάξιο.",
"Strategist order: finish the {0} ({1} m)":"Εντολή στρατηγού: ολοκλήρωσε το {0} ({1} m)",
"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"Στρατηγός: σήμανση ⌖ σε συγκέντρωση εχθρού, {0} m — πλήγμα πυροβολικού σε 8 δευτερόλεπτα. Μην πλησιάσεις!",
"MLRS \"Grad\" ×{0}: salvo at the strategist's mark":"Εκτοξευτές «Grad» ×{0}: ομοβροντία στη σήμανση του στρατηγού",
"a heavy MG for 90 s":"βαρύ πολυβόλο για 90 s",
"incendiary rounds for 60 s":"εμπρηστικά πυρομαχικά για 60 s",
"3 rockets with no cooldown":"3 ρουκέτες χωρίς επαναφόρτιση",
"Weapon cache: ":"Κρύπτη: ",
" · grenades and mags full":" · χειροβομβίδες και γεμιστήρες γεμάτα",
"⌖ ARTILLERY":"⌖ ΠΛΗΓΜΑ ΠΥΡΟΒΟΛΙΚΟΥ",
"STRATEGIST'S MARK":"ΣΗΜΑΝΣΗ ΣΤΡΑΤΗΓΟΥ",
