"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Χτίσιμο από στρατιώτες: E (στο κινητό «Είσοδος») σε δικό σου εργοτάξιο — ο στρατιώτης χτίζει μόνος του, οι σύντροφοι κοντά βοηθούν. Αν οι μηχανικοί είναι απασχολημένοι, ο στρατηγός ζητά μόνος του βοήθεια — σήμανση «ΕΡΓΟΤΑΞΙΟ».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Σημάνσεις στρατηγού: ο στρατηγός βάζει ⌖ σε συγκέντρωση εχθρών κοντά σου — 8 s αργότερα χτυπά το πυροβολικό και οι κοντινοί φίλιοι εκτοξευτές «Grad» κάνουν ομοβροντία. Και το δικό σου πλήγμα πυροβολικού από τη στρατηγική γίνεται με υποστήριξη «Grad».",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Κρύπτες όπλων σε εμπορευματοκιβώτια και συντριμμένους δορυφόρους (📦 ορατό από 70 m): E — βαρύ πολυβόλο για 90 s, εμπρηστικά ή ρουκέτες, συν γεμάτες χειροβομβίδες. Έρπεις: Ctrl — μπρούμυτα / όρθιος (χαμηλότερα, πιο σταθερή σκόπευση, αλλά αργά).",
"Anonymous statistics":"Ανώνυμα στατιστικά",
"no names or emails: version, device, play time — to make the game better":"χωρίς ονόματα και email: έκδοση, συσκευή, χρόνος παιχνιδιού — για να γίνεται το παιχνίδι καλύτερο",
"Anonymous statistics (no names or emails)":"Ανώνυμα στατιστικά (χωρίς ονόματα και email)",
"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"Κινηματογραφικό split-screen, χωρίς Πυρήνα και σήραγγες, χτίσιμο από στρατιώτες, σημάνσεις στρατηγού, κρύπτες, έρπεις, μενού προγραμματιστή",
"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Τρεις τρόποι stick στο κινητό, απλή στρατηγική, πολυβόλο οχήματος, ανάγλυφο με φαράγγια, κλάσεις ομάδων, εκρηκτικά",
"Lite mode, two-stick phone controls":"Ελαφρύς τρόπος, χειρισμός κινητού με δύο stick",
