"Do not like the new version — play the one you are used to. The choice is remembered; every version has its own saves and settings (these stay safe). An old version is loaded only when chosen.":"Δεν σου αρέσει η νέα έκδοση — παίξε αυτήν που έχεις συνηθίσει. Η επιλογή απομνημονεύεται· κάθε έκδοση έχει δικές της αποθηκεύσεις και ρυθμίσεις (αυτές δεν χάνονται). Η παλιά έκδοση φορτώνεται μόνο όταν την επιλέξεις.",
