"last enemy nearby, tank, HQ":"τελευταίος εχθρός κοντά, άρμα, Στρατηγείο",
"corner; F7 — collapse":"στη γωνία· F7 — σύμπτυξη",
"Link copied":"Ο σύνδεσμος αντιγράφηκε",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ Παίξε τώρα» — το πρώτο κουμπί του μενού: σύντομη πτήση κάτω από τον ουρανό-πύλη και κατευθείαν στη μάχη (παράλειψη με οποιοδήποτε πλήκτρο ή πάτημα).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Τα χτυπήματα γίνονται αισθητά: μεταλλικός ήχος και σπινθήρες, δείκτης εξόντωσης στο στόχαστρο (στο κεφάλι — κίτρινος), σειρά ×N, ομαλό τράνταγμα από εκρήξεις, αργή κίνηση σε βασικές εξοντώσεις. Το τράνταγμα, η αργή κίνηση και η υπόδειξη απενεργοποιούνται στις Ρυθμίσεις.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Αποτέλεσμα αγώνα: χρόνος, εξοντώσεις, καλύτερη σειρά, ★ MVP και καλύτερη ομάδα, κάρτα αγώνα — «⇪ Κοινοποίηση», PNG ή σύνδεσμος προς το παιχνίδι.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Υπόδειξη «τι να κάνεις τώρα» αριστερά κάτω από τους πόρους: εντολή του AI-στρατηγού, σημείο προς κατάληψη, επίθεση του Σμήνους. ✕ ή F7 — σύμπτυξη.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Η μάχη αποθηκεύεται μόνη της αν κλείσεις ή κρύψεις την καρτέλα — «⟲ Συνέχεια» στο μενού.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Η έκδοση v7.5 παραμένει στο μενού «🕘 Έκδοση παιχνιδιού» — σε περίπτωση που δεν σου αρέσει η νέα. Πλέον στέλνονται ανώνυμα στατιστικά (χωρίς ονόματα και email)· απενεργοποίηση — στις Ρυθμίσεις.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«Παίξε τώρα», ανταπόκριση χτυπημάτων, αποτέλεσμα αγώνα με κάρτα, υπόδειξη «τι να κάνεις», αυτόματη αποθήκευση",
"and older: v7.5, v7.4, milestones v1–v7.0":"και παλαιότερες: v7.5, v7.4, ορόσημα v1–v7.0",
"New in v7.6":"Τι νέο στο v7.6",
"NEW IN v7.6":"ΤΙ ΝΕΟ ΣΤΟ v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Επιλογή φατρίας πριν από τον αγώνα: «Κοινοπραξία» (βαρύ πεζικό με θωράκιση ισχύος, θωράκιση και πυροβολικό) ή «Σμήνος» (ταχύτητα, κοπάδια drone, βαριά πυρά με παραμόρφωση). Το AI παίζει με την άλλη. Η επιλογή απομνημονεύεται.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Κάθε φατρία έχει δικά της οχήματα και μοναδικά: η Κοινοπραξία — το άρμα «Ρινόκερος» και «Κεραμίτικες πλάκες», το Σμήνος — «Κοπάδι drone» και «Τζετπάκ φάσης». Η ισορροπία ελέγχθηκε με αγώνες bot.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Κρατήρες εκρήξεων: το πυροβολικό, οι ρουκέτες και τα κανόνια των αρμάτων ανοίγουν λάκκους στον μετεωρίτη — μπορείς να περπατάς και να οδηγείς μέσα τους και να καλύπτεσαι εκεί.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Θέα τρίτου προσώπου για τον στρατιώτη (V, απομνημονεύεται· στο κινητό — Χειρισμός) και ομαλή κάμερα οχήματος με σημάδι που δείχνει πού θα χτυπήσει το κανόνι.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Η v7.6 παραμένει στο μενού «🕘 Έκδοση παιχνιδιού», αν την προτιμάς.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Φατρίες Κοινοπραξία / Σμήνος με επιλογή πριν από τον αγώνα, κρατήρες εκρήξεων, θέα τρίτου προσώπου",
"and older: v7.6, v7.5, milestones v1–v7.0":"και παλαιότερες: v7.6, v7.5, ορόσημα v1–v7.0",
