"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"Ραδιόφωνο Portal Meteor ενεργό/ανενεργό ([ ] — κομμάτι, Shift+[ ] — ένταση)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 δεξιά — Ραδιόφωνο Portal Meteor: μουσική του EDMITRY την ώρα της μάχης.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Ραδιόφωνο Portal Meteor: μουσική του EDMITRY την ώρα της μάχης. [ ] — κομμάτι.",
"Radio Portal Meteor (EDMITRY): volume":"Ραδιόφωνο Portal Meteor (EDMITRY): ένταση",
"Radio: start by itself in battle":"Ραδιόφωνο: αυτόματη εκκίνηση στη μάχη",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Ρομπο-νίντζα: σάιμποργκ με κατάνα. Ξεκλειδώνεται στον Στρατώνα με την έρευνα «Πρωτόκολλο „Σκιά“» (χρειάζεται εργοστάσιο μηχανών). Τηλεμεταφέρεται μόνη της σε ζώνες του εχθρού, κόβει τους εχθρούς κομμάτια (χωρίς αίμα — σπίθες), κάνει εφόδους, ρίχνει σουρίκεν και μονομαχεί με τον εχθρικό νίντζα. Κατάκτησέ την — λειτουργία AUTO ή χειροκίνητος έλεγχος (στο κινητό — δικά της κουμπιά).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Ραδιόφωνο Portal Meteor: 103 κομμάτια του EDMITRY μέσα στο παιχνίδι. Πλήκτρο 5 (αλλάζει), στο κινητό — ☰ → Ρυθμίσεις → Ήχος. Ένταση και «αυτόματη εκκίνηση στη μάχη» στις ρυθμίσεις· η μουσική χαμηλώνει στις εκρήξεις και κάτω από τη φωνή του ασυρμάτου.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Νέες γλώσσες: ουζμπεκικά και τατζικικά — πλήρως· κινεζικά, ισπανικά, πορτογαλικά — μερικώς. Νέα επιλογή γλώσσας στο μενού δίπλα στο «Νέος αγώνας».",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Κινητό: το «απόκρυψη εικονιδίων» 👁 μαζεύει τα υπόλοιπα κουμπιά σε μια τακτική στήλη στη δεξιά άκρη· η κατακόρυφη προβολή δεν επικαλύπτεται πια· iPhone — το παιχνίδι δεν συγκρούεται με τις κινήσεις του Safari και το «Κοινοποίηση → Προσθήκη στην αρχική οθόνη» το ανοίγει σε πλήρη οθόνη.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Από την v7.8.1: μενού ☰ στη γωνία (παύση, επανεκκίνηση, εκπαίδευση, γραφικά), χωρίς αυτόματο Dendy, κουμπί ενέργειας ✋ στο κινητό. Οι v7.8.1 και v7.8 παραμένουν στο μενού «🕘 Έκδοση παιχνιδιού».",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Ρομπο-νίντζα, ραδιόφωνο EDMITRY, ουζμπεκικά και τατζικικά, ευκολία στο κινητό και στο iPhone",
