"The new squad is selected — RMB on the red \"ATTACK\" marker.":"Η νέα ομάδα επιλέχθηκε — δεξί κλικ στην κόκκινη ένδειξη «ΕΠΙΘΕΣΗ».",
"The new squad is selected — tap the red \"ATTACK\" marker.":"Η νέα ομάδα επιλέχθηκε — πάτα την κόκκινη ένδειξη «ΕΠΙΘΕΣΗ».",
