"✈ AIR RAID! Swarm carpet bombing — get off the red strip!":"✈ ΕΝΑΕΡΙΑ ΕΠΙΘΕΣΗ! Βομβαρδισμός με χαλί του Σμήνους — φύγε από την κόκκινη λωρίδα!",
"♨ AIR RAID! Swarm napalm — get out of the red circle!":"♨ ΕΝΑΕΡΙΑ ΕΠΙΘΕΣΗ! Ναπάλμ του Σμήνους — φύγε από τον κόκκινο κύκλο!",
