"Carpet bombing":"Βομβαρδισμός με χαλί",
"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"Το βομβαρδιστικό ρίχνει 10 βόμβες σε λωρίδα 80 m, πλησιάζοντας από τη βάση σου (στη μάχη — κατά μήκος της κατεύθυνσης του βλέμματός σου). Μετά από 3.5 s, αφήνει κρατήρες.",
"Napalm":"Ναπάλμ",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Ζώνη φωτιάς 12 m καίει για 9 δευτερόλεπτα: συνεχής ζημιά, καταστολή, καπνός. Μετά από 2.5 s. Ανάβει το μεθάνιο.",
"Bomber: target received, inbound!":"Βομβαρδιστικό: ο στόχος λήφθηκε, πλησιάζουμε!",
"Attack jet: napalm inbound!":"Αεροσκάφος εφόδου: ναπάλμ καθ' οδόν!",
"Support: crate, recon, \"Grad\", artillery, carpet bombing, napalm (then 1–6)":"Υποστήριξη: κιβώτιο, αναγνώριση, «Γκραντ», πλήγμα πυροβολικού, βομβαρδισμός με χαλί, ναπάλμ (μετά 1–6)",
"☄ Meteor shower in 10 s — take cover: the rock hangar, under a ridge!":"☄ Βροχή μετεωριτών σε 10 s — μπες σε κάλυψη: το υπόστεγο στους βράχους, κάτω από κορυφογραμμή!",
"Warning: meteor shower! Everyone take cover":"Προσοχή: βροχή μετεωριτών! Όλοι σε κάλυψη",
