"no squads within 70 m of the burrow — select squads and RMB/tap the burrow":"δεν υπάρχουν ομάδες σε 70 m από τη φωλιά — επίλεξε ομάδες και δεξί κλικ/πάτημα στη φωλιά",
"Digging: {0} s. The enemy will hear it 10 s before breakthrough":"Εκσκαφή: {0} s. Ο εχθρός θα το ακούσει 10 s πριν την έξοδο",
