"Dig the exit":"Άνοιγμα εξόδου",
"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"Σμήνος. Διάλεξε σημείο έως 220 m — η έξοδος ανοίγει σε 24 s. 10 s πριν, ο εχθρός ακούει βουητό και βλέπει σκόνη.",
"Squads into the tunnel":"Ομάδες — στη σήραγγα",
