"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"Κοινοπραξία. Από τα 12:00. Εδώ συναρμολογείται το υπερβαρύ άρμα «Προπύργιο» (ένα ανά στρατό).",
"Incubator":"Εκκολαπτήριο",
