"Super-heavy tank \"Bastion\"":"Υπερβαρύ άρμα «Προπύργιο»",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Κοινοπραξία. Αρχηγός: 15000 αντοχή, κανόνι, 2 πολυβόλα, ρουκέτες. Πολύ αργό. Αδύναμο σημείο — η πρύμνη. Ένα ανά στρατό.",
"Walker \"Reaper\"":"Βαδιστής «Θεριστής»",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Σμήνος. Αρχηγός: 12500 αντοχή, ακτίνα παραμόρφωσης, καταπάτημα. Περνά πάνω από οδοφράγματα. Αδύναμο σημείο — ο πυρήνας από κάτω. Ένας ανά στρατό.",
