"Light and medium vehicles go into the nearest open tunnel":"Τα ελαφρά και μεσαία οχήματα μπαίνουν στην πλησιέστερη ανοιχτή σήραγγα",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Σμήνος. Οι ομάδες σε 70 m από τη φωλιά (και οι επιλεγμένες) και τα επιλεγμένα ελαφρά/μεσαία οχήματα («Τσακάλι», «Σφυρί», «Γκραντ») περνούν από τη σήραγγα. Ή: επίλεξε και δεξί κλικ/πάτημα στη φωλιά.",
