"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Τάπητας βομβών και ναπάλμ: στόχευση, περιστροφή της λωρίδας, προειδοποίηση εχθρού, κλήση από τη μάχη",
