"Living world: your units ask for help, heroes give quests. Card on the right — ✕ to dismiss.":"Ζωντανός κόσμος: οι δικοί σου ζητούν βοήθεια, οι ήρωες δίνουν αποστολές. Κάρτα δεξιά — ✕ για απόκρυψη.",
