"SABOTAGE":"ΔΟΛΙΟΦΘΟΡΑ",
"Living world: requests, hero quests, breakthrough ops":"Ζωντανός κόσμος: αιτήματα, αποστολές ηρώων, επιχειρήσεις ανατροπής",
"Living world":"Ζωντανός κόσμος",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Οι δικοί σου ζητούν βοήθεια και σε ανταμείβουν, οι ήρωες δίνουν αποστολές, ένα κολλημένο μέτωπο σπάει με επιχείρηση",
"A request":"Αίτημα των δικών σου",
"Breakthrough":"Ανατροπή",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Οι δικοί σου ζητούν κάποτε βοήθεια: φωνή στο ραδιόφωνο, κάρτα «ΑΙΤΗΜΑ» και δείκτης ✋. Μια ομάδα καρφώθηκε — εξόντωσε τους εχθρούς κοντά της. Ανταμοιβή: στρατιώτης με κάψουλα από τη βάση, όπλο από το αμάξωμα του μπάγκι, θέση πυροβολητή ή κάλυψη από την τροχιά. Δεν θέλεις — ✕ ή απλώς αγνόησέ το.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Ο βετεράνος ανιχνευτής «Κουκουβάγια» προτείνει αποστολή. Y — αποδοχή (N — άρνηση). Πήγαινε στον δείκτη ★, καθάρισε τη φρουρά και μείνε 3 s δίπλα στον πιλότο — μπαίνει στην ομάδα σου.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Το μέτωπο κόλλησε — η Μεραρχία (HQ) προτείνει τροπή της μάχης. Y — αποδοχή. Κράτα τον αναμεταδότη 8 s χωρίς εχθρούς κοντά: ο χάρτης του εχθρού φαίνεται 60 s. Η γεννήτρια — οι πυργίσκοι του εχθρού σιωπούν 2 λεπτά. Στη λειτουργία Στρατηγού — «Ανάθεση σε ομάδα». Το ίδιο μπορεί να κάνει κι ο εχθρός: πρόσεχε το ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Οι δικοί σου ζητούν βοήθεια: κάρτα «ΑΙΤΗΜΑ» και δείκτης ✋. Εξόντωσε τους εχθρούς κοντά στην καρφωμένη ομάδα — θα πάρεις ανταμοιβή. ✕ — παράλειψη.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Ο ήρωας «Κουκουβάγια» προτείνει αποστολή — πάτα «Αποδοχή». Πήγαινε στο ★, καθάρισε τη φρουρά, μείνε δίπλα στον πιλότο.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Το μέτωπο κόλλησε — πάτα «Αποδοχή» και κράτα τον αναμεταδότη 8 s: ο χάρτης του εχθρού ανοίγει για ένα λεπτό.",
