"Button remapping comes in a later version. Keyboard, mouse and touch work as before; hints switch to the gamepad by themselves while you use it.":"Η αντιστοίχιση κουμπιών έρχεται σε επόμενη έκδοση. Το πληκτρολόγιο, το ποντίκι και η οθόνη αφής δουλεύουν όπως πριν· οι υποδείξεις αλλάζουν μόνες τους σε χειριστήριο όσο το χρησιμοποιείς.",
