"📖 Encyclopedia — ☰ → pause: units, bosses, anomalies":"📖 Εγκυκλοπαίδεια — στο μενού ☰ → παύση: μονάδες, αρχηγοί, ανωμαλίες",
"📖 Encyclopedia — in the pause menu (Esc): units, bosses, anomalies":"📖 Εγκυκλοπαίδεια — στην παύση (Esc): μονάδες, αρχηγοί, ανωμαλίες",
