"saved":"αποθηκεύτηκε",
"1. Start a screen recording with your voice (PC — OBS, phone — the built-in screen recorder with mic) and turn on Feedback mode here.":"1. Ξεκίνα εγγραφή οθόνης με φωνή (PC — OBS, κινητό — η ενσωματωμένη εγγραφή οθόνης με μικρόφωνο) και ενεργοποίησε εδώ τη «Λειτουργία σχολίων».",
"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Παίξε και σκέψου φωναχτά: τι δεν είναι σαφές, τι ενοχλεί, τι σου αρέσει. Η γωνία δείχνει έκδοση, ώρα και FPS — με αυτά η εγγραφή αντιστοιχίζεται με τις σημειώσεις.",
"3. When something matters — take a note: PC ":"3. Όταν κάτι έχει σημασία — κράτα σημείωση: PC ",
